	static int[][] rows(int[] values, int width)
	{
		int[][] rows = new int[values.length / width][width];
		for (int row = 0; row < rows.length; row++)
		{
			System.arraycopy(values, row * width, rows[row], 0, width);
		}
		return rows;
	}
	static double[][] rows(double[] values, int width)
	{
		double[][] rows = new double[values.length / width][width];
		for (int row = 0; row < rows.length; row++)
		{
			System.arraycopy(values, row * width, rows[row], 0, width);
		}
		return rows;
	}
